[Better Approach - 2] -Using Bottom-Up DP (Tabulation) – O(n × m) Time and O(n × m) SpaceThe approach is similar to the previous one, just instead of breaking down the problem recursively, we iteratively build up the solution by calculating in bottom-up manner. The idea is to create a 2-D array. Then fill the values using dp[i][j] = 1 + min(dp[i+1][j], dp[i][j+1], dp[i+1][j+1]) for cells having value equal to 1. Otherwise, set dp[i][j] = 0. 
            C++

    #include <iostream>
#include<vector>
#include<algorithm>
using namespace std;

int maxSquare(vector<vector<int>> &mat) {
    int n = mat.size(), m = mat[0].size();
    int ans = 0;

    // Create 2d array for tabulation
    vector<vector<int>> dp(n+1, vector<int>(m+1, 0));

    // Fill the dp 
    for (int i=n-1; i>=0; i--) {
        for (int j=m-1; j>=0; j--) {

            // If square cannot be formed
            if (mat[i][j] == 0) {
                dp[i][j] = 0;
                continue;
            }

            // check all 3 sides
            dp[i][j] = 1 + min({dp[i][j+1], 
            dp[i+1][j], dp[i+1][j+1]});

            ans = max(ans, dp[i][j]);
        }
    }

    return ans;
}

